'use strict';
/* Sonidos reales de perro (recortados, normalizados, mono 22 kHz). Créditos y licencias en CREDITOS.txt.
   - bark1, bark2, woof2: «Barking of a dog.ogg», Amada44, CC BY-SA 3.0 (Wikimedia Commons)
   - bark3, bark4: «Barking of a dog 2.ogg», Amada44, CC BY-SA 3.0 (Wikimedia Commons)
   - yip, whine, yap: «Puppy at a night.ogg», Knites, CC0 (Wikimedia Commons) */
const DOG_SOUNDS = {"bark1": "data:audio/wav;base64,", "bark2": "data:audio/wav;base64,", "bark3": "data:audio/wav;base64,", "bark4": "data:audio/wav;base64,", "woof2": "data:audio/wav;base64,", "yip": "data:audio/wav;base64,", "whine": "data:audio/wav;base64,", "yap": "data:audio/wav;base64,"};
// Reproduce un sonido de Luna. Cuanto más pequeña, más agudo (sin preservar el tono).
const DOG_PITCH = [1.45, 1.32, 1.18, 1.05, 1.0];
function dogSound(kind, size = 2, vol = 0.8) {
  if (typeof isMuted === 'function' && isMuted()) return;
  const pool = { bark: ['bark1', 'bark2', 'bark3', 'bark4'], happy: ['woof2', 'yip', 'yap'], sad: ['whine'], yip: ['yip', 'yap'] }[kind] || [kind];
  const id = pool[Math.floor(Math.random() * pool.length)];
  const src = DOG_SOUNDS[id];
  if (!src) return;
  try {
    const a = new Audio(src);
    a.preservesPitch = false; a.mozPreservesPitch = false; a.webkitPreservesPitch = false;
    a.playbackRate = (DOG_PITCH[size] || 1.15) * (0.96 + Math.random() * 0.08);
    a.volume = vol;
    a.play().catch(() => {});
  } catch (e) { /* sin audio */ }
}
